package zapret

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// The SmartDNS block that lives next to the zapret one must survive every
// rewrite: both features share /etc/hosts and neither owns the whole file.
const smartdnsBlock = `# ========================================================
# Auto-generated by Ex3-UI SmartDNS (Geo-unblock)
# Do not edit manually - managed automatically
1.2.3.4 chatgpt.com
# ========================================================
`

func TestUpdateHostsBlockAppendsAndPreservesOtherEntries(t *testing.T) {
	path := filepath.Join(t.TempDir(), "hosts")
	if err := os.WriteFile(path, []byte("127.0.0.1 localhost\n\n"+smartdnsBlock), 0o644); err != nil {
		t.Fatal(err)
	}
	if err := updateHostsBlock(path); err != nil {
		t.Fatal(err)
	}
	got, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	text := string(got)
	if !strings.Contains(text, "127.0.0.1 localhost") {
		t.Error("user entries were dropped")
	}
	if !strings.Contains(text, "1.2.3.4 chatgpt.com") {
		t.Error("SmartDNS block was dropped")
	}
	if !strings.Contains(text, "140.82.121.3 github.com") {
		t.Error("github pin is missing")
	}
	if !strings.Contains(text, "162.159.135.232 updates.discord.com") {
		t.Error("discord pin is missing")
	}
}

func TestUpdateHostsBlockIsIdempotent(t *testing.T) {
	path := filepath.Join(t.TempDir(), "hosts")
	if err := os.WriteFile(path, []byte("127.0.0.1 localhost\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	for i := 0; i < 3; i++ {
		if err := updateHostsBlock(path); err != nil {
			t.Fatal(err)
		}
	}
	got, _ := os.ReadFile(path)
	if n := strings.Count(string(got), hostsBlockMarker); n != 1 {
		t.Fatalf("block written %d times, want 1", n)
	}
	if n := strings.Count(string(got), "140.82.121.3 github.com"); n != 1 {
		t.Fatalf("github pin written %d times, want 1", n)
	}
}

func TestRemoveHostsBlockKeepsSmartDNS(t *testing.T) {
	path := filepath.Join(t.TempDir(), "hosts")
	if err := os.WriteFile(path, []byte("127.0.0.1 localhost\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	if err := updateHostsBlock(path); err != nil {
		t.Fatal(err)
	}
	if err := removeHostsBlock(path); err != nil {
		t.Fatal(err)
	}
	got, _ := os.ReadFile(path)
	text := string(got)
	if strings.Contains(text, hostsBlockMarker) || strings.Contains(text, "140.82.121.3 github.com") {
		t.Error("zapret block survived removal")
	}
	if !strings.Contains(text, "127.0.0.1 localhost") {
		t.Error("user entries were dropped")
	}

	// And the SmartDNS block stays when both are present.
	if err := os.WriteFile(path, []byte(smartdnsBlock), 0o644); err != nil {
		t.Fatal(err)
	}
	if err := updateHostsBlock(path); err != nil {
		t.Fatal(err)
	}
	if err := removeHostsBlock(path); err != nil {
		t.Fatal(err)
	}
	got, _ = os.ReadFile(path)
	if !strings.Contains(string(got), "1.2.3.4 chatgpt.com") {
		t.Error("removing the zapret block removed the SmartDNS block")
	}
}
